trait Audited extends Payments {
  protected def sink: AuditSink

  abstract override def pay(p: Payment): Receipt = {
    val actor = SecurityContext.subject
    sink.record(actor, "pay", p.id, "attempt")
    try { val r = super.pay(p); sink.record(actor, "pay", p.id, "ok"); r }
    catch { case e: Throwable => sink.record(actor, "pay", p.id, "failed"); throw e }
  }
}

class AuditedPayments(protected val sink: AuditSink) extends BasePayments with Audited
